import { Router, type RequestHandler } from "express";
import { Errors } from "../errors";
import { createUploadMiddleware } from "../middleware/upload";
import type { ImportRecord } from "../repo/importRepo";
import type { ImportService } from "../services/importService";

// importId values are UUIDs generated by this service. Anything else cannot
// exist, so answer 404 without touching the database.
const IMPORT_ID =
  /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;

/**
 * Express types route params as string | string[]. This route has exactly one
 * :importId, so anything other than a plain string is treated as not found.
 */
function importIdParam(value: string | string[] | undefined): string {
  return typeof value === "string" ? value : "";
}

/** The public details shape. Built field by field, so nothing internal leaks. */
function toDetails(record: ImportRecord) {
  return {
    importId: record.importId,
    documentType: record.documentType,
    status: record.status,
    contentHash: record.contentHash,
    detectedEncoding: record.detectedEncoding,
    summary: record.summary,
    warnings: record.warnings,
    errors: record.errors,
    ...(record.tallyResponse ? { tallyResponse: record.tallyResponse } : {}),
  };
}

export function createImportsRouter(
  service: ImportService,
  maxUploadBytes: number,
): Router {
  const router = Router();

  // Accounting data must never be cached by browsers or intermediaries.
  router.use((_req, res, next) => {
    res.setHeader("Cache-Control", "no-store");
    next();
  });

  const requireImportId: RequestHandler = (req, _res, next) => {
    if (!IMPORT_ID.test(importIdParam(req.params["importId"]))) {
      next(Errors.notFound("Import"));
      return;
    }
    next();
  };

  router.post("/", createUploadMiddleware(maxUploadBytes), (req, res) => {
    // The upload middleware guarantees req.file is present.
    const file = req.file!;
    const { record, duplicate } = service.importDocument({
      bytes: file.buffer,
      filename: file.originalname,
    });

    res
      .status(duplicate ? 200 : 201)
      .location(`/api/tally/imports/${record.importId}`)
      .json({
        importId: record.importId,
        documentType: record.documentType,
        status: record.status,
        duplicate,
        summary: record.summary,
      });
  });

  router.get("/:importId", requireImportId, (req, res) => {
    const record = service.getImportDetails(
      importIdParam(req.params["importId"]),
    );
    res.status(200).json(toDetails(record));
  });

  router.get("/:importId/vouchers", requireImportId, (req, res) => {
    const items = service.getVouchers(importIdParam(req.params["importId"]));
    res.status(200).json({ items, count: items.length });
  });

  return router;
}
